      color-scheme: dark;
      --bg: #0a0d14;
      --bg-elevated: #111827;
      --bg-card: rgba(18, 24, 38, 0.86);
      --bg-card-strong: rgba(26, 33, 51, 0.96);
      --text: #f4f7fb;
      --muted: #a7b1c3;
      --muted-2: #7e899d;
      --line: rgba(180, 194, 224, 0.16);
      --line-strong: rgba(213, 224, 255, 0.28);
      --accent: #8ef0c7;
      --accent-2: #7d8cff;
      --accent-3: #ffb05b;
      --shadow: 0 28px 70px rgba(0, 0, 0, 0.42);
      --radius-xl: 30px;
      --radius-lg: 22px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --container: 1180px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(125, 140, 255, 0.24), transparent 30%),
        radial-gradient(circle at 80% 10%, rgba(142, 240, 199, 0.18), transparent 26%),
        radial-gradient(circle at 60% 80%, rgba(255, 176, 91, 0.12), transparent 24%),
        linear-gradient(180deg, #0b1020 0%, #080b11 55%, #05070c 100%);
      color: var(--text);
      line-height: 1.5;
      min-height: 100vh;
      text-rendering: optimizeLegibility;
      -webkit-font-smoothing: antialiased;
    }

    body::before,
    body::after {
      content: "";
      position: fixed;
      inset: auto;
      width: 30rem;
      height: 30rem;
      border-radius: 50%;
      pointer-events: none;
      filter: blur(60px);
      opacity: 0.3;
      z-index: -1;
    }

    body::before {
      top: -10rem;
      left: -10rem;
      background: rgba(125, 140, 255, 0.26);
    }

    body::after {
      right: -12rem;
      bottom: -12rem;
      background: rgba(142, 240, 199, 0.2);
    }

    img {
      display: block;
      max-width: 100%;
    }

    a {
      color: inherit;
      text-decoration-thickness: 0.08em;
      text-underline-offset: 0.18em;
    }

    a:hover {
      color: var(--accent);
    }

    :focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.85rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: var(--bg);
      transform: translateY(-180%);
      transition: transform 150ms ease;
      z-index: 10;
    }

    .skip-link:focus,
    .skip-link:active {
      transform: translateY(0);
    }

    .shell {
      width: min(calc(100% - 2rem), var(--container));
      margin-inline: auto;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 8;
      backdrop-filter: blur(18px);
      background: linear-gradient(180deg, rgba(6, 10, 17, 0.9), rgba(6, 10, 17, 0.55));
      border-bottom: 1px solid rgba(180, 194, 224, 0.1);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      text-decoration: none;
    }

    .brand-mark {
      display: inline-grid;
      place-items: center;
      width: 2.6rem;
      height: 2.6rem;
      border-radius: 0.95rem;
      background: linear-gradient(145deg, rgba(142, 240, 199, 0.95), rgba(125, 140, 255, 0.95));
      color: #05070c;
      box-shadow: 0 12px 30px rgba(125, 140, 255, 0.22);
    }

    nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.35rem;
      list-style: none;
      margin: 0;
      padding: 0;
    }

    nav a {
      display: inline-flex;
      align-items: center;
      min-height: 2.75rem;
      padding: 0 0.9rem;
      border-radius: 999px;
      color: var(--muted);
      text-decoration: none;
      border: 1px solid transparent;
    }

    nav a:hover,
    nav a:focus-visible {
      color: var(--text);
      border-color: var(--line-strong);
      background: rgba(255, 255, 255, 0.03);
    }

    main {
      padding: 2rem 0 4rem;
    }

    .hero {
      display: grid;
      gap: 1.4rem;
      grid-template-columns: minmax(0, 1.15fr) minmax(280px, 0.85fr);
      align-items: stretch;
      margin-top: 1rem;
    }

    .hero-copy,
    .hero-panel,
    .section-card,
    .deal-card,
    .story-card {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
      border: 1px solid var(--line);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.5rem, 2vw, 2.4rem);
      position: relative;
      overflow: hidden;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
    }

    .eyebrow::before {
      content: "";
      width: 0.7rem;
      height: 0.7rem;
      border-radius: 999px;
      background: currentColor;
      box-shadow: 0 0 0 6px rgba(142, 240, 199, 0.12);
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      margin: 1rem 0 0.8rem;
      max-width: 12ch;
      font-size: clamp(2.6rem, 6vw, 5.5rem);
      line-height: 0.95;
      letter-spacing: -0.05em;
    }

    .lede {
      max-width: 58ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
      margin-top: 1.5rem;
    }

    .button,
    .button-secondary,
    .deal-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.85rem 1.15rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font-weight: 700;
      text-decoration: none;
      transition: transform 150ms ease, background 150ms ease, border-color 150ms ease;
    }

    .button {
      background: linear-gradient(135deg, var(--accent), #b8ffd6);
      color: #05110e;
    }

    .button-secondary,
    .deal-link {
      background: rgba(255, 255, 255, 0.03);
      color: var(--text);
      border-color: var(--line);
    }

    .button:hover,
    .button-secondary:hover,
    .deal-link:hover {
      transform: translateY(-1px);
    }

    .hero-panel {
      padding: 1.2rem;
      display: grid;
      gap: 1rem;
    }

    .panel-block {
      border-radius: var(--radius-lg);
      padding: 1rem;
      background:
        linear-gradient(180deg, rgba(125, 140, 255, 0.15), rgba(18, 24, 38, 0.8)),
        rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(185, 196, 224, 0.12);
    }

    .panel-block strong {
      display: block;
      margin-top: 0.2rem;
      font-size: 1.1rem;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .stat {
      padding: 0.95rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--line);
    }

    .stat .value {
      display: block;
      font-size: 1.3rem;
      font-weight: 800;
      color: var(--text);
    }

    .stat .label {
      color: var(--muted);
      font-size: 0.88rem;
    }

    .section {
      margin-top: 1.4rem;
    }

    .section-card {
      padding: clamp(1.2rem, 2vw, 1.6rem);
    }

    .section-header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.15rem;
    }

    .section-header p {
      color: var(--muted);
      max-width: 56ch;
    }

    .grid-products {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(12, minmax(0, 1fr));
    }

    .product-card {
      grid-column: span 4;
      display: grid;
      grid-template-rows: auto 1fr;
      overflow: hidden;
      border-radius: var(--radius-lg);
      border: 1px solid var(--line);
      background: var(--bg-card);
      min-height: 100%;
    }

    .product-art {
      aspect-ratio: 4 / 3;
      background: radial-gradient(circle at 30% 20%, rgba(255, 255, 255, 0.14), transparent 30%), linear-gradient(145deg, rgba(125, 140, 255, 0.18), rgba(142, 240, 199, 0.08));
      border-bottom: 1px solid var(--line);
      padding: 1rem;
    }

    .product-body {
      padding: 1rem;
      display: grid;
      gap: 0.8rem;
    }

    .meta-line {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: start;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .meta-line strong {
      color: var(--text);
      font-size: 1rem;
    }

    .pill-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      min-height: 2rem;
      padding: 0 0.65rem;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.05);
      color: var(--muted);
      font-size: 0.82rem;
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .product-card .button {
      justify-self: start;
      min-height: 2.8rem;
      padding-inline: 1rem;
    }

    .deal-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.6fr);
    }

    .deal-card {
      padding: 1.4rem;
      background:
        radial-gradient(circle at top right, rgba(255, 176, 91, 0.2), transparent 32%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
    }

    .deal-card p,
    .story-card p {
      color: var(--muted);
    }

    .deal-promo {
      display: grid;
      gap: 0.85rem;
      padding: 1.1rem;
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--line);
    }

    .deal-promo strong {
      font-size: 1.6rem;
      letter-spacing: -0.04em;
    }

    .deal-timer {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      color: var(--accent-3);
      font-weight: 700;
    }

    .story-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: minmax(0, 1.15fr) repeat(2, minmax(0, 0.85fr));
    }

    .story-card {
      overflow: hidden;
      background: var(--bg-card-strong);
    }

    .story-media {
      aspect-ratio: 16 / 10;
      background:
        linear-gradient(145deg, rgba(125, 140, 255, 0.22), rgba(142, 240, 199, 0.08)),
        radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.16), transparent 25%);
      border-bottom: 1px solid var(--line);
    }

    .story-body {
      padding: 1rem;
      display: grid;
      gap: 0.75rem;
    }

    .story-body .eyebrow {
      color: var(--accent-3);
    }

    .story-body .eyebrow::before {
      box-shadow: 0 0 0 6px rgba(255, 176, 91, 0.12);
    }

    .story-card time {
      color: var(--muted-2);
      font-size: 0.88rem;
    }

    .section-footer {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: center;
      margin-top: 1rem;
      color: var(--muted);
    }

    .status {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    footer {
      padding: 1.5rem 0 2rem;
      color: var(--muted-2);
    }

    .footer-row {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      border-top: 1px solid rgba(180, 194, 224, 0.12);
      padding-top: 1rem;
    }

    @media (max-width: 980px) {
      .hero,
      .deal-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .product-card {
        grid-column: span 6;
      }

      .section-header,
      .section-footer {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (max-width: 680px) {
      .topbar {
        flex-direction: column;
        align-items: start;
      }

      nav ul {
        gap: 0.2rem;
      }

      nav a {
        padding-inline: 0.8rem;
      }

      h1 {
        max-width: 10ch;
        font-size: clamp(2.35rem, 15vw, 4.4rem);
      }

      .stats {
        grid-template-columns: 1fr;
      }

      .product-card {
        grid-column: 1 / -1;
      }
    }

    @media (forced-colors: active) {
      :root {
        --text: CanvasText;
        --muted: CanvasText;
      }

      body,
      header,
      .hero-copy,
      .hero-panel,
      .section-card,
      .deal-card,
      .story-card,
      .product-card,
      .panel-block,
      .stat,
      .deal-promo {
        forced-color-adjust: auto;
        background: Canvas;
        color: CanvasText;
        border-color: CanvasText;
        box-shadow: none;
      }

      .button,
      .button-secondary,
      .deal-link,
      nav a {
        forced-color-adjust: auto;
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }

      .brand-mark {
        background: ButtonFace;
        color: ButtonText;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header>
    <div class="shell topbar">
      <a class="brand" href="#" aria-label="Aster &amp; Co. home">
        <span class="brand-mark" aria-hidden="true">A</span>
        <span>Aster &amp; Co.</span>
      </a>

      <nav aria-label="Primary">
        <ul>
          <li><a href="#featured-products">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
          <li><a href="#footer">Brand</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="maincontent" tabindex="-1">
    <div class="shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <span class="eyebrow">New season / dark essentials</span>
          <h1 id="hero-title">Refined layers for everyday light.</h1>
          <p class="lede">
            Aster &amp; Co. curates elevated staples, statement outerwear, and tactile home accents for a polished wardrobe with an easy, modern edge.
          </p>
          <div class="hero-actions">
            <a class="button" href="#featured-products">Shop featured</a>
            <a class="button-secondary" href="#editorial">Read the edit</a>
          </div>
        </div>

        <aside class="hero-panel" aria-label="Store highlights">
          <div class="panel-block">
            <span class="eyebrow">Drop of the week</span>
            <strong>Tailored warmth, softened with texture.</strong>
            <p>From brushed knits to weather-ready outerwear, the collection is built for clean silhouettes and long wear.</p>
          </div>

          <div class="stats" aria-label="Performance highlights">
            <div class="stat">
              <span class="value">48h</span>
              <span class="label">Fresh edits</span>
            </div>
            <div class="stat">
              <span class="value">3-day</span>
              <span class="label">Priority delivery</span>
            </div>
            <div class="stat">
              <span class="value">24/7</span>
              <span class="label">Styling support</span>
            </div>
          </div>
        </aside>
      </section>

      <section class="section section-card" id="featured-products" aria-labelledby="featured-title">
        <div class="section-header">
          <div>
            <span class="eyebrow">Featured products</span>
            <h2 id="featured-title">Signature picks for the season.</h2>
          </div>
          <p>Designed to mix across your wardrobe, these pieces balance tailored structure with soft finishes and subtle utility.</p>
        </div>

        <div class="grid-products" id="product-grid" aria-live="polite"></div>
        <p class="status" id="bag-status" aria-live="polite"></p>
      </section>

      <section class="section section-card" id="deals" aria-labelledby="deals-title">
        <div class="section-header">
          <div>
            <span class="eyebrow">Deals</span>
            <h2 id="deals-title">Timed offers with premium finishes.</h2>
          </div>
          <p>Bundle your essentials, save on standout layers, and unlock complimentary shipping on orders over $150.</p>
        </div>

        <div class="deal-grid">
          <article class="deal-card">
            <span class="eyebrow">Flash event</span>
            <h3>Members get 20% off outerwear tonight.</h3>
            <p>
              Add a coat and knitwear to your bag before midnight. The edit includes weatherproof shells, relaxed tailoring, and warm layering pieces.
            </p>
            <div class="deal-promo">
              <span class="deal-timer" id="deal-timer" aria-live="polite">Offer refreshes in 00:00:00</span>
              <strong>Use code NIGHTFALL20</strong>
              <a class="deal-link" href="#featured-products">Shop the edit</a>
            </div>
          </article>

          <article class="deal-card">
            <span class="eyebrow">Bundle savings</span>
            <h3>Build a three-piece capsule, save 15%.</h3>
            <p>Combine any shirt, pant, and layer from the collection to unlock automatic pricing at checkout.</p>
            <div class="deal-promo">
              <strong>Capsule staples</strong>
              <p>Pair neutral tones with one accent piece for a wardrobe that stretches further.</p>
              <a class="deal-link" href="#editorial">See styling notes</a>
            </div>
          </article>
        </div>
      </section>

      <section class="section section-card" id="editorial" aria-labelledby="editorial-title">
        <div class="section-header">
          <div>
            <span class="eyebrow">Editorial content</span>
            <h2 id="editorial-title">Stories, styling, and perspective.</h2>
          </div>
          <p>Browse the journal for fit guidance, fabric notes, and the inspiration behind this month&apos;s collection.</p>
        </div>

        <div class="story-grid" id="story-grid"></div>
      </section>
    </div>
  </main>

  <footer id="footer">
    <div class="shell footer-row">
      <p>&copy; <span id="year"></span> Aster &amp; Co. Modern retail for home and wardrobe.</p>
      <p><a href="#maincontent">Back to top</a></p>
    </div>
  </footer>

