      padding-inline: 1rem;
    }

    .deal-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.6fr);
    }

    .deal-card {
      padding: 1.4rem;
      background:
        radial-gradient(circle at top right, rgba(255, 176, 91, 0.2), transparent 32%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
    }

    .deal-card p,
    .story-card p {
      color: var(--muted);
    }

    .deal-promo {
      display: grid;
      gap: 0.85rem;
      padding: 1.1rem;
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--line);
    }

    .deal-promo strong {
      font-size: 1.6rem;
      letter-spacing: -0.04em;
    }

    .deal-timer {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      color: var(--accent-3);
      font-weight: 700;
    }

    .story-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: minmax(0, 1.15fr) repeat(2, minmax(0, 0.85fr));
    }

    .story-card {
      overflow: hidden;
      background: var(--bg-card-strong);
    }

    .story-media {
      aspect-ratio: 16 / 10;
      background:
        linear-gradient(145deg, rgba(125, 140, 255, 0.22), rgba(142, 240, 199, 0.08)),
        radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.16), transparent 25%);
      border-bottom: 1px solid var(--line);
    }

    .story-body {
      padding: 1rem;
      display: grid;
      gap: 0.75rem;
    }

    .story-body .eyebrow {
      color: var(--accent-3);
    }

    .story-body .eyebrow::before {
      box-shadow: 0 0 0 6px rgba(255, 176, 91, 0.12);
    }

    .story-card time {
      color: var(--muted-2);
      font-size: 0.88rem;
    }

    .section-footer {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: center;
      margin-top: 1rem;
      color: var(--muted);
    }

    .status {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    footer {
      padding: 1.5rem 0 2rem;
      color: var(--muted-2);
    }

    .footer-row {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      border-top: 1px solid rgba(180, 194, 224, 0.12);
      padding-top: 1rem;
    }

    @media (max-width: 980px) {
      .hero,
      .deal-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .product-card {
        grid-column: span 6;
      }

      .section-header,
      .section-footer {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (max-width: 680px) {
      .topbar {
        flex-direction: column;
        align-items: start;
      }

      nav ul {
        gap: 0.2rem;
      }

      nav a {
        padding-inline: 0.8rem;
      }

      h1 {
        max-width: 10ch;
        font-size: clamp(2.35rem, 15vw, 4.4rem);
      }

      .stats {
        grid-template-columns: 1fr;
      }

      .product-card {
        grid-column: 1 / -1;
      }
    }

    @media (forced-colors: active) {
      :root {
        --text: CanvasText;
        --muted: CanvasText;
      }

      body,
      header,
      .hero-copy,
      .hero-panel,
      .section-card,
      .deal-card,
      .story-card,
      .product-card,
      .panel-block,
      .stat,
      .deal-promo {
        forced-color-adjust: auto;
        background: Canvas;
        color: CanvasText;
        border-color: CanvasText;
        box-shadow: none;
      }

      .button,
      .button-secondary,
      .deal-link,
      nav a {
        forced-color-adjust: auto;
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }

      .brand-mark {
        background: ButtonFace;
        color: ButtonText;
      }
