<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header>
    <div class="shell topbar">
      <a class="brand" href="#" aria-label="Aster &amp; Co. home">
        <span class="brand-mark" aria-hidden="true">A</span>
        <span>Aster &amp; Co.</span>
      </a>

      <nav aria-label="Primary">
        <ul>
          <li><a href="#featured-products">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
          <li><a href="#footer">Brand</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="maincontent" tabindex="-1">
    <div class="shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <span class="eyebrow">New season / dark essentials</span>
          <h1 id="hero-title">Refined layers for everyday light.</h1>
          <p class="lede">
            Aster &amp; Co. curates elevated staples, statement outerwear, and tactile home accents for a polished wardrobe with an easy, modern edge.
          </p>
          <div class="hero-actions">
            <a class="button" href="#featured-products">Shop featured</a>
            <a class="button-secondary" href="#editorial">Read the edit</a>
          </div>
        </div>

        <aside class="hero-panel" aria-label="Store highlights">
          <div class="panel-block">
            <span class="eyebrow">Drop of the week</span>
            <strong>Tailored warmth, softened with texture.</strong>
            <p>From brushed knits to weather-ready outerwear, the collection is built for clean silhouettes and long wear.</p>
          </div>

          <div class="stats" aria-label="Performance highlights">
            <div class="stat">
              <span class="value">48h</span>
              <span class="label">Fresh edits</span>
            </div>
            <div class="stat">
              <span class="value">3-day</span>
              <span class="label">Priority delivery</span>
            </div>
            <div class="stat">
              <span class="value">24/7</span>
              <span class="label">Styling support</span>
            </div>
          </div>
        </aside>
      </section>

      <section class="section section-card" id="featured-products" aria-labelledby="featured-title">
        <div class="section-header">
          <div>
            <span class="eyebrow">Featured products</span>
            <h2 id="featured-title">Signature picks for the season.</h2>
          </div>
          <p>Designed to mix across your wardrobe, these pieces balance tailored structure with soft finishes and subtle utility.</p>
        </div>

        <div class="grid-products" id="product-grid"></div>
        <p class="status" id="bag-status" aria-live="polite"></p>
      </section>

      <section class="section section-card" id="deals" aria-labelledby="deals-title">
        <div class="section-header">
          <div>
            <span class="eyebrow">Deals</span>
            <h2 id="deals-title">Timed offers with premium finishes.</h2>
          </div>
          <p>Bundle your essentials, save on standout layers, and unlock complimentary shipping on orders over $150.</p>
        </div>

        <div class="deal-grid">
          <article class="deal-card">
            <span class="eyebrow">Flash event</span>
            <h3>Members get 20% off outerwear tonight.</h3>
            <p>
              Add a coat and knitwear to your bag before midnight. The edit includes weatherproof shells, relaxed tailoring, and warm layering pieces.
            </p>
            <div class="deal-promo">
              <span class="deal-timer" id="deal-timer">Offer refreshes in 00:00:00</span>
              <strong>Use code NIGHTFALL20</strong>
              <a class="deal-link" href="#featured-products">Shop the edit</a>
            </div>
          </article>

          <article class="deal-card">
            <span class="eyebrow">Bundle savings</span>
            <h3>Build a three-piece capsule, save 15%.</h3>
            <p>Combine any shirt, pant, and layer from the collection to unlock automatic pricing at checkout.</p>
            <div class="deal-promo">
              <strong>Capsule staples</strong>
              <p>Pair neutral tones with one accent piece for a wardrobe that stretches further.</p>
              <a class="deal-link" href="#editorial">See styling notes</a>
            </div>
          </article>
        </div>
      </section>

      <section class="section section-card" id="editorial" aria-labelledby="editorial-title">
        <div class="section-header">
          <div>
            <span class="eyebrow">Editorial content</span>
            <h2 id="editorial-title">Stories, styling, and perspective.</h2>
          </div>
          <p>Browse the journal for fit guidance, fabric notes, and the inspiration behind this month&apos;s collection.</p>
        </div>

        <div class="story-grid" id="story-grid"></div>
      </section>
    </div>
  </main>

  <footer id="footer">
    <div class="shell footer-row">
      <p>&copy; <span id="year"></span> Aster &amp; Co. Modern retail for home and wardrobe.</p>
      <p><a href="#maincontent">Back to top</a></p>
    </div>
  </footer>

  <script>
    const products = [
      {
        name: "Wool Blend Overshirt",
        category: "Outerwear",
        price: "$168",
        note: "Warm hand-feel, structured drape, easy layering.",
        tags: ["New", "Limited"],
        art: ["#8ef0c7", "#7d8cff", "#121a2a"]
      },
      {
        name: "Monolith Knit Crew",
        category: "Knitwear",
        price: "$94",
        note: "Soft brushed knit with a clean neckline and quiet texture.",
        tags: ["Best seller", "Organic cotton"],
        art: ["#ffb05b", "#8ef0c7", "#161c2d"]
      },
      {
        name: "Slate Pleated Trouser",
        category: "Tailoring",
        price: "$132",
        note: "High-rise structure and a relaxed leg for daily wear.",
        tags: ["Tailored", "Machine washable"],
        art: ["#7d8cff", "#d7e0ff", "#111827"]
      },
      {
        name: "Cloud Loop Sneaker",
        category: "Footwear",
        price: "$118",
        note: "Lightweight cushioning and a minimal profile.",
        tags: ["Comfort", "All day"],
        art: ["#8ef0c7", "#f4f7fb", "#0f172a"]
      },
      {
        name: "Terra Sling Bag",
        category: "Accessories",
        price: "$78",
        note: "A compact carry with adjustable strap and matte hardware.",
        tags: ["Editors' pick", "Vegan leather"],
        art: ["#ffb05b", "#5b6276", "#171d2b"]
      },
      {
        name: "Studio Candle Set",
        category: "Home",
        price: "$58",
        note: "A softly spiced scent profile with a smooth mineral finish.",
        tags: ["Giftable", "Hand-poured"],
        art: ["#d7e0ff", "#8ef0c7", "#101827"]
      }
    ];

    const stories = [
      {
        eyebrow: "Journal / fit guide",
        title: "How to layer dark neutrals without flattening the look.",
        body: "Start with matte textures, add one reflective surface, and finish with a lighter accessory to keep the silhouette dimensional.",
        meta: "Read time 4 min",
        imageLabel: "Abstract editorial image for layering guide"
      },
      {
        eyebrow: "Lookbook / fabrics",
        title: "Why brushed cotton and compact wool work so well together.",
        body: "The mix holds shape while still moving with the body, making it ideal for office days, weekend travel, and cooler evenings.",
        meta: "Read time 3 min",
        imageLabel: "Abstract editorial image for fabric story"
      },
      {
        eyebrow: "Field notes / styling",
        title: "Five details that make a capsule wardrobe feel complete.",
        body: "A crisp collar, consistent hardware, tonal shoes, a signature outer layer, and one piece with tactile contrast can unify the whole edit.",
        meta: "Read time 5 min",
        imageLabel: "Abstract editorial image for styling notes"
      }
    ];

    const svgDataUri = (name, colors) => {
      const [a, b, c] = colors;
      const svg = `
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 600" role="img" aria-labelledby="title desc">
          <title>${name}</title>
          <desc>Abstract product illustration with layered gradients and soft geometric forms.</desc>
          <defs>
            <linearGradient id="g1" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stop-color="${a}" stop-opacity="0.95" />
              <stop offset="100%" stop-color="${b}" stop-opacity="0.92" />
            </linearGradient>
            <radialGradient id="g2" cx="30%" cy="30%" r="70%">
              <stop offset="0%" stop-color="#ffffff" stop-opacity="0.5" />
              <stop offset="60%" stop-color="${c}" stop-opacity="0.2" />
              <stop offset="100%" stop-color="${c}" stop-opacity="0" />
            </radialGradient>
          </defs>
          <rect width="800" height="600" rx="48" fill="${c}" />
          <circle cx="180" cy="160" r="130" fill="url(#g2)" />
          <circle cx="612" cy="138" r="92" fill="rgba(255,255,255,0.12)" />
          <rect x="170" y="128" width="380" height="290" rx="34" fill="url(#g1)" opacity="0.85" />
          <path d="M122 420 C250 320, 390 304, 650 410" stroke="${a}" stroke-width="34" stroke-linecap="round" fill="none" opacity="0.65" />
          <path d="M190 456 C322 392, 484 390, 610 448" stroke="${b}" stroke-width="24" stroke-linecap="round" fill="none" opacity="0.55" />
          <circle cx="622" cy="408" r="54" fill="${a}" opacity="0.45" />
        </svg>
      `;
      return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
    };

    const productGrid = document.getElementById("product-grid");
    const storyGrid = document.getElementById("story-grid");
    const year = document.getElementById("year");
    const bagStatus = document.getElementById("bag-status");
    const timer = document.getElementById("deal-timer");

    const renderProducts = () => {
      productGrid.innerHTML = products.map((product, index) => `
        <article class="product-card">
          <div class="product-art">
            <img src="${svgDataUri(product.name, product.art)}" alt="${product.name}" />
          </div>
          <div class="product-body">
            <div class="meta-line">
              <div>
                <strong>${product.name}</strong>
                <div>${product.category}</div>
              </div>
              <strong aria-label="Price ${product.price}">${product.price}</strong>
            </div>
            <p>${product.note}</p>
            <div class="pill-row" aria-label="${product.name} highlights">
              ${product.tags.map((tag) => `<span class="pill">${tag}</span>`).join("")}
            </div>
            <button class="button" type="button" data-product="${index}">Add to bag</button>
          </div>
        </article>
      `).join("");
    };

    const renderStories = () => {
      storyGrid.innerHTML = stories.map((story, index) => `
        <article class="story-card ${index === 0 ? "story-card--featured" : ""}">
          <div class="story-media" aria-hidden="true"></div>
          <div class="story-body">
            <span class="eyebrow">${story.eyebrow}</span>
            <h3>${story.title}</h3>
            <p>${story.body}</p>
            <time>${story.meta}</time>
          </div>
        </article>
      `).join("");
    };

    const updateTimer = () => {
      const now = new Date();
      const target = new Date(now);
      target.setHours(23, 59, 59, 999);

      const diff = target - now;
      const hours = Math.floor(diff / 36e5).toString().padStart(2, "0");
      const minutes = Math.floor(diff % 36e5 / 6e4).toString().padStart(2, "0");
      const seconds = Math.floor(diff % 6e4 / 1000).toString().padStart(2, "0");

      timer.textContent = `Offer refreshes in ${hours}:${minutes}:${seconds}`;
    };

    productGrid.addEventListener("click", (event) => {
      const button = event.target.closest("button[data-product]");
      if (!button) return;

      const product = products[Number(button.dataset.product)];
      bagStatus.textContent = `${product.name} added to your bag.`;
      button.textContent = "Added";

      window.setTimeout(() => {
        button.textContent = "Add to bag";
      }, 1500);
    });

    renderProducts();
    renderStories();
    updateTimer();
    window.setInterval(updateTimer, 1000);
    year.textContent = String(new Date().getFullYear());
  </script>
</body>
</html>
